  "Une broche ne reçoit qu’un fil. Pour relier plusieurs fils au même point, passez par une breadboard : le câblage automatique s’en sert.": "A pin takes only one wire. To connect several wires to the same point, go through a breadboard: auto-wiring uses breadboards this way.",
