  "Aucune carte à programmer": "No board to program",
  "Ajoutez une carte (ESP32, Arduino Uno, Pico…) depuis la bibliothèque, puis écrivez son programme ou donnez des règles à ses composants.": "Add a board (ESP32, Arduino Uno, Pico…) from the library, then write its program or give rules to its components.",
  "Carte programmée": "Programmed board",
  "Quand une mesure change, un effecteur réagit": "When a reading changes, an actuator reacts",
  "Règle": "Rule",
  "Une règle relie une mesure à des actions : « quand BTN1 est appuyé, LED1 s’allume ». Chaque branche peut contenir plusieurs actions et d’autres conditions imbriquées. Le code Arduino s’écrit tout seul ci-dessous. Vous pouvez aussi sélectionner un composant puis « Programmer ».": "A rule links a reading to actions: “when BTN1 is pressed, LED1 turns on”. Each branch can hold several actions and other nested conditions. The Arduino code below writes itself. You can also select a component, then click “Program”.",
  "États par défaut": "Default states",
  "Un effecteur prend son état par défaut au démarrage, et, si vous le choisissez, chaque fois qu’aucune règle ne le commande. Un capteur ou une entrée part de sa valeur par défaut à chaque lancement de la simulation.": "An actuator takes its default state at startup and, if you choose, whenever no rule is controlling it. A sensor or input starts from its default value each time the simulation starts.",
  "Remplacer le code par celui des règles et du montage": "Replace the code with the one generated from the rules and the circuit",
