  "Rendu image par image en MP4 : chaque image est calculée à son instant exact, la vidéo reste fluide quelle que soit la machine. Repli sur l’enregistrement en temps réel si le système ne sait pas encoder.": "Frame-by-frame MP4 rendering: each frame is computed at its exact moment, so the video stays smooth on any machine. Falls back to real-time recording if the system can’t encode.",
