  "{0}Travaux pratiques": "{0}Practical labs",
  "Un laboratoire d’électronique sans matériel : chaque TP part d’un montage, guide pas à pas et vérifie votre travail (câblage, programme, comportement, mesures au multimètre). Votre projet est mis de côté pendant le TP.": "An electronics lab without equipment: each lab starts from a circuit, guides you step by step and checks your work (wiring, program, behaviour, multimeter measurements). Your project is set aside during the lab.",
