  "10, dont 2 communs reliés": "10, including 2 common pins tied together",
  "Sept segments en forme de 8, plus un point : chacun est une LED, et toutes les cathodes rejoignent le commun. Allumer une combinaison de segments forme un chiffre.": "Seven segments shaped like an 8, plus a dot: each one is an LED, and all the cathodes join the common pin. Lighting a combination of segments forms a digit.",
  "Compteur, minuteur": "Counter, timer",
