  "Animations lumineuses": "Light animations",
  "Alimenter une longue bande par la carte : chute de tension, couleurs fausses, carte qui redémarre.": "Powering a long strip from the board: voltage drop, wrong colors, the board resets.",
  "Oublier la masse commune entre l’alimentation des LED et la carte.": "Forgetting the common ground between the LED power supply and the board.",
  "Brancher les données sur DOUT au lieu de DIN.": "Connecting data to DOUT instead of DIN.",
  "Seuils": "Forward voltage",
  "≈ 2 V pour le rouge, ≈ 3 V pour le vert et le bleu": "≈ 2 V for red, ≈ 3 V for green and blue",
  "20 mA maximum par couleur": "20 mA maximum per color",
  "Trois LED dans le même boîtier. En dosant chacune avec la PWM, on mélange les couleurs : rouge + vert = jaune, les trois ensemble = blanc.": "Three LEDs in one package. By setting the brightness of each one with PWM, you mix colors: red + green = yellow, all three together = white.",
  "Voyant multicolore": "Multicolor indicator light",
  "Lampe d’ambiance": "Mood lamp",
  "Indiquer un état par une couleur": "Show a state with a color",
  "Une seule résistance sur la cathode commune : les couleurs s’influencent.": "A single resistor on the common cathode: the colors affect each other.",
  "LED à anode commune : relier le commun au + et inverser la logique (255 = éteint).": "Common-anode LED: connect the common pin to + and invert the logic (255 = off).",
  "actif (oscillateur intégré)": "active (built-in oscillator)",
  "3,3 à 5 V, ≈ 25 mA": "3.3 to 5 V, ≈ 25 mA",
  "Son": "Sound",
  "≈ 2,3 kHz, fréquence fixe": "≈ 2.3 kHz, fixed frequency",
  "Polarité": "Polarity",
  "Un oscillateur intégré fait vibrer une pastille piézoélectrique dès que le buzzer est alimenté. Un buzzer passif, lui, n’a pas d’oscillateur et suit la fréquence envoyée par tone().": "A built-in oscillator makes a piezo disc vibrate as soon as the buzzer is powered. A passive buzzer has no oscillator: it follows the frequency sent by tone().",
  "Bip de confirmation": "Confirmation beep",
  "Minuteur": "Timer",
  "Utiliser tone() sur un buzzer actif : son grésillant.": "Using tone() on an active buzzer: crackly sound.",
  "Inverser + et − : il ne sonne pas.": "Swapping + and −: it stays silent.",
  "Impédance": "Impedance",
  "Une bobine placée dans le champ d’un aimant pousse une membrane au rythme du signal électrique, ce qui fait vibrer l’air.": "A coil sitting in a magnet’s field pushes a cone in time with the electrical signal, which makes the air vibrate.",
  "Mélodies avec tone()": "Melodies with tone()",
  "Sons de jeu, alertes": "Game sounds, alerts",
  "Le brancher sans résistance : 8 Ω demandent bien plus de courant qu’une broche n’en fournit.": "Connecting it without a resistor: 8 Ω draws far more current than a pin can supply.",
  "Bobine": "Coil",
  "Contacts": "Contacts",
  "10 A sous 125 V~, 7 A sous 240 V~ ou 28 V⎓": "10 A at 125 V~, 7 A at 240 V~ or 28 V⎓",
  "Commande": "Control",
  "transistor et diode intégrés, souvent active à l’état bas": "built-in transistor and diode, often active low",
  "Bornier": "Terminal block",
  "COM, NO (normalement ouvert), NC (normalement fermé)": "COM, NO (normally open), NC (normally closed)",
  "Le courant dans la bobine crée un champ magnétique qui attire une lame : le contact COM passe de NC à NO. Le circuit commandé reste isolé de la carte.": "Current in the coil creates a magnetic field that pulls a metal blade: the COM contact switches from NC to NO. The switched circuit stays isolated from the board.",
  "Allumer une lampe, une pompe, un ventilateur": "Switch on a lamp, a pump, a fan",
  "Couper un appareil à distance": "Switch off a device remotely",
  "Travailler sur le secteur 230 V sous tension : danger de mort.": "Working on live 230 V mains: risk of death.",
  "Alimenter la bobine en 3,3 V : le relais colle mal ou pas du tout.": "Powering the coil at 3.3 V: the relay switches unreliably or not at all.",
  "Croire que HIGH active le relais : sur beaucoup de modules, c’est LOW.": "Assuming HIGH turns the relay on: on many modules, it’s LOW.",
  "4,8 à 6 V, jusqu’à ≈ 650 mA bloqué": "4.8 to 6 V, up to ≈ 650 mA when stalled",
  "Couple": "Torque",
  "≈ 1,8 kg·cm": "≈ 1.8 kg·cm",
  "Vitesse": "Speed",
  "0,1 s pour 60°": "0.1 s per 60°",
  "Débattement": "Range of motion",
  "impulsion de 0,5 à 2,4 ms toutes les 20 ms (50 Hz)": "0.5 to 2.4 ms pulse every 20 ms (50 Hz)",
  "marron GND · rouge VCC · orange signal": "brown GND · red VCC · orange signal",
  "Un moteur, des engrenages et un potentiomètre fixé sur l’axe : le circuit interne compare la position mesurée à celle demandée par la largeur d’impulsion, et corrige.": "A motor, gears and a potentiometer fixed to the shaft: the internal circuit compares the measured position with the one requested by the pulse width, and corrects it.",
  "Bras robotisé, pince": "Robot arm, gripper",
  "Barrière, trappe": "Barrier gate, hatch",
  "Orienter un capteur": "Aim a sensor",
  "Plusieurs servos sur le 5 V de la carte : redémarrages.": "Several servos on the board’s 5 V: the board resets.",
  "Forcer en butée : les engrenages en plastique cassent.": "Forcing it against its end stop: the plastic gears break.",
  "Sur ESP32, la bibliothèque Servo standard ne fonctionne pas : utilisez ESP32Servo.": "On ESP32, the standard Servo library doesn’t work: use ESP32Servo.",
  "3 à 6 V": "3 to 6 V",
  "100 à 250 mA à vide, plus de 1 A bloqué": "100 to 250 mA with no load, over 1 A when stalled",
  "par un pilote (L298N, TB6612…)": "through a driver (L298N, TB6612…)",
  "Le courant dans les bobines du rotor crée une force dans le champ des aimants : l’axe tourne. Inverser la polarité inverse le sens ; la tension moyenne, réglée en PWM, fixe la vitesse.": "Current in the rotor coils creates a force in the magnets’ field: the shaft turns. Reversing the polarity reverses the direction; the average voltage, set with PWM, sets the speed.",
  "Roues d’un robot": "Robot wheels",
  "Ventilateur, pompe": "Fan, pump",
  "Le brancher sur une broche de la carte.": "Connecting it directly to a board pin.",
  "Oublier le condensateur de 100 nF entre ses bornes : parasites qui perturbent la carte.": "Forgetting the 100 nF capacitor across its terminals: electrical noise disturbs the board.",
  "L’alimenter avec une pile 9 V : elle s’effondre en quelques minutes.": "Powering it from a 9 V battery: the battery dies within minutes.",
  "unipolaire 4 phases, réduction 1:64": "unipolar, 4-phase, 1:64 gear reduction",
  "2048 pas par tour": "2048 steps per revolution",
  "≈ 0,3 kg·cm": "≈ 0.3 kg·cm",
  "Pilote": "Driver",
  "carte ULN2003 avec 4 LED témoins": "ULN2003 board with 4 indicator LEDs",
  "Les bobines sont alimentées dans un ordre précis : l’aimant du rotor suit le champ, pas après pas. On sait exactement de combien l’axe a tourné, sans capteur.": "The coils are energized in a precise order: the rotor magnet follows the field, step by step. You know exactly how far the shaft has turned, without a sensor.",
