  "Store, distributeur": "Window blind, dispenser",
  "Positionnement précis et lent": "Slow, precise positioning",
  "Mauvais ordre des broches dans le code (IN1-IN3-IN2-IN4) : le moteur vibre sans tourner.": "Wrong pin order in the code (IN1-IN3-IN2-IN4): the motor vibrates without turning.",
  "Vitesse trop élevée (plus de 15 tours/min) : il décroche.": "Speed too high (over 15 RPM): it stalls.",
  "Bobines alimentées à l’arrêt : il chauffe inutilement.": "Coils left powered when stopped: it heats up for nothing.",
