  "Charges": "Loads",
  "2 moteurs à courant continu, ou 1 moteur pas à pas bipolaire": "2 DC motors, or 1 bipolar stepper motor",
  "Un pont en H par voie : quatre transistors appliquent la tension au moteur dans un sens ou dans l’autre. ENA et ENB autorisent chaque voie ; en PWM, ils règlent la vitesse.": "One H-bridge per channel: four transistors apply the voltage to the motor in one direction or the other. ENA and ENB enable each channel; with PWM, they set the speed.",
