  "céramique, non polarisé": "ceramic, non-polarized",
  "Tension": "Voltage",
  "Placé au plus près d’une puce, il stocke un peu de charge et la restitue lors des appels de courant très brefs : il filtre les parasites de l’alimentation.": "Placed as close as possible to a chip, it stores a little charge and releases it during very short current spikes: it filters noise out of the power supply.",
