  "Anti-parasite aux bornes d’un moteur": "Noise suppression across a motor",
  "Anti-rebond matériel avec une résistance": "Hardware debounce with a resistor",
  "Le placer loin de la puce : il ne sert presque à rien.": "Placing it far from the chip: it does almost nothing.",
