  "maximum imprimé sur le boîtier, souvent 16 ou 25 V": "maximum printed on the case, often 16 or 25 V",
  "Un réservoir d’énergie : il amortit les chutes de tension quand un moteur, un servo ou une radio tire brusquement beaucoup de courant.": "An energy reservoir: it smooths out voltage dips when a motor, servo or radio suddenly draws a lot of current.",
