  // sim/boards.js
  "entrée": "input",
  "résistance de tirage interne": "internal pull-up resistor",
  "broche de démarrage (strapping) : son niveau au démarrage choisit le mode de boot, à garder en dernier recours": "strapping pin: its level at startup selects the boot mode; use only as a last resort",
  "entrée seulement, sans résistance de tirage interne": "input only, no internal pull-up resistor",
  "broche de démarrage : tirée au niveau haut au démarrage, elle empêche l’ESP32 de démarrer": "strapping pin: if pulled high at startup, it prevents the ESP32 from booting",
  "reliée à la LED bleue de la carte ; broche de démarrage": "connected to the board’s blue LED; strapping pin",
  "TX du port série USB": "TX of the USB serial port",
  "RX du port série USB": "RX of the USB serial port",
  "elle appartient à l’ADC1, qui reste utilisable quand le Wi-Fi est actif (l’ADC2 ne l’est pas).": "it belongs to ADC1, which remains usable while Wi-Fi is on (ADC2 doesn’t).",
  "À éviter : D12, D2, D5 et D15 (broches de démarrage), TX0 et RX0 (port série USB). D34, D35, VP et VN sont des entrées seulement.": "Avoid: D12, D2, D5 and D15 (strapping pins), TX0 and RX0 (USB serial port). D34, D35, VP and VN are input only.",
  "VIN fournit le 5 V de l’USB : pratique pour les modules qui exigent 5 V, mais leurs signaux de sortie doivent rester à 3,3 V.": "VIN supplies the 5 V from USB: handy for modules that require 5 V, but their output signals must stay at 3.3 V.",
  "GPIO 16 : ni PWM, ni interruption, ni tirage interne vers le haut": "GPIO 16: no PWM, no interrupts, no internal pull-up",
  "broche de démarrage tirée au niveau haut : elle ne doit pas être à la masse au démarrage": "strapping pin pulled high: it must not be grounded at startup",
  "reliée à la LED de la carte ; broche de démarrage tirée au niveau haut": "connected to the board’s LED; strapping pin pulled high",
  "broche de démarrage tirée au niveau bas": "strapping pin pulled low",
  "seule entrée analogique, 0 à 3,3 V sur cette carte": "only analog input, 0 to 3.3 V on this board",
  "reliée à la mémoire flash : à ne jamais utiliser": "connected to the flash memory: never use it",
  "c’est la seule entrée analogique de l’ESP8266.": "it is the ESP8266’s only analog input.",
  "Une seule entrée analogique (A0). D3, D4 et D8 sont des broches de démarrage, D0 n’a ni PWM ni tirage vers le haut.": "Only one analog input (A0). D3, D4 and D8 are strapping pins; D0 has neither PWM nor pull-up.",
  "interruption externe INT0": "external interrupt INT0",
  "interruption externe INT1": "external interrupt INT1",
  "reliée à la LED « L » de la carte": "connected to the board’s “L” LED",
  "même broche que A4": "same pin as A4",
  "même broche que A5": "same pin as A5",
  "D0 et D1 servent au téléversement par USB. Le bus I2C matériel est sur SDA/SCL (A4/A5), le SPI sur D10 à D13.": "D0 and D1 are used for uploading over USB. The hardware I2C bus is on SDA/SCL (A4/A5), SPI on D10 to D13.",
  "Logique 5 V : les modules prévus pour 3,3 V seulement demandent un adaptateur de niveau.": "5 V logic: modules designed for 3.3 V only need a level shifter.",
  "entrée analogique seulement": "analog input only",
  "Le bus I2C est sur A4 (SDA) et A5 (SCL), le SPI sur D10 à D13. A6 et A7 sont des entrées analogiques seulement.": "The I2C bus is on A4 (SDA) and A5 (SCL), SPI on D10 to D13. A6 and A7 are analog inputs only.",
  "Pico": "Pico",
  "seules GP26 à GP28 sont reliées à l’ADC.": "only GP26 to GP28 are connected to the ADC.",
  "3V3 sort 3,3 V, VBUS le 5 V de l’USB. Entrées analogiques : GP26 à GP28. Aucune broche n’accepte 5 V.": "3V3 outputs 3.3 V, VBUS the 5 V from USB. Analog inputs: GP26 to GP28. No pin is 5 V tolerant.",
