  "Carte importée, famille {0} : logique {1} V, ADC {2} bits.": "Imported board, {0} family: {1} V logic, {2}-bit ADC.",
  "Les rôles des broches sont déduits de leur nom (GPIO4, IO4, D4, GP4, A0, 3V3, 5V, GND…). Renommez une broche pour corriger son rôle.": "Pin roles are inferred from their names (GPIO4, IO4, D4, GP4, A0, 3V3, 5V, GND…). Rename a pin to correct its role.",
