  // sim/circuit.js, faults.js : bouton monté en interrupteur, dans l’autre sens ou avec résistance de rappel
  "pinMode({0}, INPUT); // résistance de rappel : relâché LOW, appuyé HIGH": "pinMode({0}, INPUT); // pull-down resistor: released LOW, pressed HIGH",
  "résistance de rappel vers la masse manquante : au repos l’entrée flotte": "no pull-down resistor to ground: the input floats when released",
  "appuyer relie directement l’alimentation à la masse": "pressing connects the power supply straight to ground",
  "{0} : résistance de rappel manquante": "{0}: missing pull-down resistor",
  "Bouton relié à l’alimentation : appuyé, l’entrée passe à HIGH. Relâché, plus rien ne la relie : elle « flotte » et lit des 0 et des 1 au hasard. Une résistance vers la masse la ramène à LOW au repos.": "Button wired to the power supply: when pressed, the input goes HIGH. When released, nothing holds it anymore: it “floats” and reads random 0s and 1s. A resistor to ground pulls it back to LOW at rest.",
  "{0} : court-circuit quand on appuie": "{0}: short circuit when pressed",
  "Le bouton relie directement le + à la masse : appuyer met la pile ou l’alimentation en court-circuit. Rien ne limite le courant : la pile chauffe et se vide, un fil fin peut brûler, un port USB se coupe.": "The button connects + straight to ground: pressing it short-circuits the battery or power supply. Nothing limits the current: the battery heats up and drains, a thin wire can burn, a USB port shuts down.",
  "interrupteur fermé : le courant passe": "switch closed: current flows",
  "interrupteur ouvert : le courant ne passe pas": "switch open: no current flows",
  // schematic/live.js, main.js : câblage sur le schéma
  "{0} et {1} sont déjà reliées.": "{0} and {1} are already connected.",
  "{0} a déjà son fil et son nœud n’a plus de point libre : ajoutez une breadboard en 3D pour y relier plusieurs fils.": "{0} already has its wire and its net has no free point left: add a breadboard in 3D to connect several wires there.",
  "Fil ajouté : {0}.": "Wire added: {0}.",
  "Fil ajouté : {0}. La broche avait déjà son fil : le nouveau part d’un point libre du même nœud.": "Wire added: {0}. The pin already had its wire, so the new one starts from a free point on the same net.",
  "Aucun fil à retirer ici.": "No wire to remove here.",
  "Fil retiré : {0}.": "Wire removed: {0}.",
  "Câbler : glissez d’une broche à une autre.": "Wiring: drag from one pin to another.",
  "déjà reliées": "already connected",
  "Relâchez ou cliquez sur une autre broche · Échap : annuler": "Release or click on another pin · Esc: cancel",
  "Glissez vers une autre broche pour les relier": "Drag to another pin to connect them",
  "clic droit : débrancher": "right-click: disconnect",
  "Clic droit ou Suppr : retirer le fil": "Right-click or Delete: remove the wire",
  // main.js, faults.js : corrections en un clic des erreurs de bouton
  "Relier à la masse": "Connect to ground",
  "Brancher sur 3V3": "Move to 3V3",
  "La carte": "The board",
  "{0} n’a pas de broche {1}.": "{0} has no {1} pin.",
  "{0} relié à la masse : appuyé, l’entrée passe à LOW (INPUT_PULLUP dans le code généré).": "{0} connected to ground: when pressed, the input goes LOW (INPUT_PULLUP in the generated code).",
  "{0} relié au 3V3 de {1} : appuyé, l’entrée reçoit 3,3 V.": "{0} connected to 3V3 on {1}: when pressed, the input gets 3.3 V.",
  "Reliez l’autre patte du bouton à la masse au lieu de l’alimentation (l’entrée utilise alors sa résistance de tirage interne, appuyé = LOW), ou ajoutez une résistance de 10 kΩ entre la broche de la carte et la masse. « Relier à la masse » fait le premier pour vous.": "Connect the other leg of the button to ground instead of the power supply (the input then uses its internal pull-up, pressed = LOW), or add a 10 kΩ resistor between the board pin and ground. “Connect to ground” does the first for you.",
  "Placez ce que le bouton commande (résistance et LED, moteur…) entre le bouton et la masse : seul, il ne doit jamais relier le + à la masse. « Retirer le fil » débranche d’abord le côté masse.": "Put what the button controls (resistor and LED, motor…) between the button and ground: on its own, it must never connect + to ground. “Remove wire” first disconnects the ground side.",
  "Reliez l’autre patte du bouton au 3V3 de la carte au lieu du 5 V : appuyé, l’entrée recevra 3,3 V. « Brancher sur 3V3 » le fait pour vous.": "Connect the other leg of the button to the board’s 3V3 instead of 5 V: when pressed, the input will get 3.3 V. “Move to 3V3” does it for you.",
  // Effecteurs sur le calcul du circuit, ventilateur, pompe, vibreur, contacts du relais, schéma éditable
  "Ventilateur 5 V": "5 V fan",
  "Mini pompe à eau 5 V": "Mini water pump 5 V",
  "Moteur vibreur": "Vibration motor",
  "Allumer une lampe, une pompe, un ventilateur : + de la pile sur COM, l’appareil sur NO": "Switch a lamp, a pump, a fan: battery + on COM, the device on NO",
  "5 V (démarre vers 2 V)": "5 V (starts at about 2 V)",
  "≈ 100 mA": "≈ 100 mA",
  "rouge + · noir −": "red + · black −",
  "transistor, relais ou pilote ; vitesse en PWM": "transistor, relay or driver; speed with PWM",
  "Un moteur sans balais : une petite électronique alimente tour à tour les bobines pour faire tourner l’hélice. Elle ne fonctionne que dans un sens de branchement.": "A brushless motor: a small circuit powers the coils in turn to spin the blades. It only works one way round.",
  "Refroidir un boîtier quand la température monte": "Cool an enclosure when the temperature rises",
  "Aérer une serre": "Ventilate a greenhouse",
  "Ventilateur de bureau commandé par un capteur": "Desk fan controlled by a sensor",
  "Le brancher à l’envers : il ne tourne pas.": "Wiring it the wrong way round: it does not spin.",
  "Le relier à une broche de la carte : 100 mA, c’est trop pour elle.": "Connecting it to a board pin: 100 mA is too much for it.",
  "L’alimenter en 9 V ou 12 V : il chauffe et s’use vite.": "Powering it with 9 V or 12 V: it heats up and wears out quickly.",
  "130 à 220 mA": "130 to 220 mA",
