  "Un moteur à courant continu fait tourner une turbine : l’eau aspirée par le bas est projetée vers la buse de sortie.": "A DC motor spins an impeller: water drawn in from below is pushed out through the outlet.",
  "Arrosage automatique quand la terre est sèche": "Automatic watering when the soil is dry",
