  "pinMode({0}, OUTPUT); // base de {1} : HIGH, le transistor conduit et {2} tourne": "pinMode({0}, OUTPUT); // base of {1}: HIGH, the transistor conducts and {2} runs",
  "// un transistor ne fait tourner que dans un sens : il faut un pont en H (L298N) pour inverser": "// a transistor only drives one direction: an H-bridge (L298N) is needed to reverse",
  "n’a pas sa base reliée (par une résistance) à": "does not have its base connected (through a resistor) to",
  "digitalWrite({0}, {1}); // {2} s’arrête": "digitalWrite({0}, {1}); // {2} stops",
  "digitalWrite({0}, {1}); // {2} tourne (contact {3} fermé)": "digitalWrite({0}, {1}); // {2} runs ({3} contact closed)",
  "// un relais ne règle pas la vitesse : tout ou rien": "// a relay cannot set the speed: on or off only",
