  "Une alimentation est reliée directement à la masse.": "A power supply is connected directly to ground.",
  "Rien ne limite le courant : fil qui chauffe, port USB qui se coupe, régulateur ou pile détruits.": "Nothing limits the current: wires heat up, the USB port shuts down, the regulator or battery gets destroyed.",
  "Retirez le fil qui relie le + à la masse : chaque alimentation doit passer par un composant.": "Remove the wire connecting + to ground: every power supply must go through a component.",
  "Deux alimentations de tensions différentes sont reliées.": "Two power supplies with different voltages are connected together.",
  "La plus forte débite dans la plus faible sans limite : régulateur qui chauffe, carte qui grille.": "The stronger one pushes current into the weaker one with no limit: the regulator overheats, the board burns out.",
  "Séparez les deux alimentations ; ne reliez que leurs masses.": "Separate the two power supplies; connect only their grounds.",
  "Dans au moins un état du montage, une source débite un courant de court-circuit.": "In at least one state of the circuit, a source delivers a short-circuit current.",
  "Un bouton, un relais ou une sortie qui ferme le circuit sans charge : la source débite des ampères.": "A button, relay or output that closes the circuit with no load: the source delivers amps.",
  "Placez une charge (résistance, LED et sa résistance, moteur) entre le contact et la masse.": "Put a load (resistor, LED with its resistor, motor) between the contact and ground.",
  "Une broche d’alimentation d’un module n’est reliée à aucune source.": "A module’s power pin is not connected to any source.",
  "Le module reste éteint : il ne répond pas, la carte lit des valeurs vides.": "The module stays off: it does not respond, and the board reads empty values.",
  "Reliez VCC à la bonne tension de la carte (3V3 ou 5V).": "Connect VCC to the right board voltage (3V3 or 5V).",
  "Un module reçoit moins que sa tension minimale.": "A module receives less than its minimum voltage.",
  "Il fonctionne mal ou pas du tout : mesures fausses, redémarrages.": "It works badly or not at all: wrong readings, restarts.",
  "Alimentez-le dans sa plage (voir sa fiche).": "Power it within its range (see its datasheet).",
  "Un module reçoit plus que sa tension maximale.": "A module receives more than its maximum voltage.",
  "Ses transistors claquent : il chauffe, peut fumer et meurt souvent pour de bon.": "Its transistors break down: it heats up, may smoke and often dies for good.",
  "Alimentez-le en 3,3 V s’il le demande, ou passez par un régulateur.": "Power it at 3.3 V if it needs that, or go through a regulator.",
  "Un composant n’a pas de chemin de retour vers la masse.": "A component has no return path to ground.",
  "Le courant ne peut pas circuler : rien ne marche.": "Current cannot flow: nothing works.",
  "Reliez sa masse (GND, cathode…) à la masse du montage.": "Connect its ground (GND, cathode…) to the circuit’s ground.",
  "Un module et la carte n’ont pas la même masse.": "A module and the board do not share the same ground.",
  "Une tension n’a de sens que par rapport à une référence : signaux illisibles.": "A voltage only means something relative to a reference: signals become unreadable.",
  "Reliez les masses entre elles.": "Connect the grounds together.",
  "Une source ou une broche d’alimentation fournit plus que ce qu’elle peut.": "A source or power pin supplies more than it can.",
  "Le régulateur chauffe et coupe, la tension s’effondre, la carte redémarre ou grille.": "The regulator heats up and cuts out, the voltage collapses, the board restarts or burns out.",
