  "Un bouton relie seul le + à la masse.": "A button alone connects + to ground.",
  "Appuyer met la source en court-circuit.": "Pressing it short-circuits the source.",
  "Mettez ce que le bouton commande entre lui et la masse.": "Put whatever the button controls between it and ground.",
  "Une broche de signal est reliée directement à une alimentation.": "A signal pin is connected directly to a power supply.",
  "Elle reste bloquée à l’état haut ; si la carte la met à LOW, sa sortie grille.": "It stays stuck high; if the board sets it LOW, its output burns out.",
  "Retirez le fil et reliez la broche à une GPIO de la carte.": "Remove the wire and connect the pin to a GPIO on the board.",
  "Une broche de signal est reliée directement à la masse.": "A signal pin is connected directly to ground.",
