  "Ajoutez un adaptateur de niveau ou utilisez une carte 3,3 V.": "Add a level shifter or use a 3.3 V board.",
  "Une ligne à drain ouvert n’a pas de résistance de tirage.": "An open-drain line has no pull-up resistor.",
  "Elle ne remonte jamais au niveau haut : aucune donnée ne passe.": "It never goes back high: no data gets through.",
  "Ajoutez la résistance de tirage (4,7 kΩ vers VDD pour la DS18B20).": "Add the pull-up resistor (4.7 kΩ to VDD for the DS18B20).",
  "Un bouton vers l’alimentation sans résistance de rappel.": "A button to the power supply with no pull-down resistor.",
  "Relâché, l’entrée flotte et lit des valeurs au hasard.": "When it is released, the input floats and reads random values.",
  "Ajoutez 10 kΩ vers la masse, ou reliez le bouton à la masse et utilisez INPUT_PULLUP.": "Add 10 kΩ to ground, or connect the button to ground and use INPUT_PULLUP.",
  "Un module est branché sur le port série USB.": "A module is connected to the USB serial port.",
