  "Utilisez d’autres broches (SoftwareSerial, Serial2).": "Use other pins (SoftwareSerial, Serial2).",
  "Dans au moins un état, une LED est traversée par plus de 20 mA (conseillé) ou 30 mA (maximum).": "In at least one state, an LED carries more than 20 mA (recommended) or 30 mA (maximum).",
  "Au-delà, elle chauffe et s’use vite ; au-delà du maximum, elle grille.": "Above that, it heats up and wears out quickly; above the maximum, it burns out.",
  "Ajoutez ou augmentez sa résistance série : R = (U − 2 V) / 0,015 A ≈ 220 Ω sous 5 V.": "Add a series resistor or increase it: R = (U − 2 V) / 0.015 A ≈ 220 Ω at 5 V.",
  "Dans au moins un état, une broche de la carte débite plus que son courant conseillé ou maximal.": "In at least one state, a board pin delivers more than its recommended or maximum current.",
