  "Dans au moins un état, le programme lit une entrée qui n’est reliée à aucun niveau.": "In at least one state, the program reads an input that is not tied to any level.",
  "Comme une variable non initialisée : l’entrée flotte et lit des 0 et des 1 au hasard.": "Like an uninitialized variable: the input floats and reads random 0s and 1s.",
  "Utilisez INPUT_PULLUP, ou ajoutez une résistance de tirage (10 kΩ).": "Use INPUT_PULLUP, or add a pull-up resistor (10 kΩ).",
  "analogWrite sur une broche sans PWM.": "analogWrite on a pin without PWM.",
  "La broche ne fait que tout ou rien : la vitesse ou la luminosité ne se règlent pas.": "The pin can only be fully on or off: speed or brightness cannot be adjusted.",
  "Choisissez une broche marquée PWM (~).": "Choose a pin marked PWM (~).",
  "analogRead sur une broche sans convertisseur.": "analogRead on a pin without a converter.",
  "La mesure ne veut rien dire.": "The reading is meaningless.",
  "Choisissez une entrée analogique (A0…).": "Choose an analog input (A0…).",
  "Le programme commande une broche reliée à rien.": "The program controls a pin connected to nothing.",
  "Le code fait une chose que le montage ne voit pas.": "The code does something the circuit never sees.",
  "Reliez le composant à cette broche, ou corrigez le numéro dans le code.": "Connect the component to this pin, or fix the number in the code.",
  "Un composant est relié à la carte mais le programme ne s’en sert jamais.": "A component is connected to the board but the program never uses it.",
  "Il ne fera rien : souvent un numéro de broche qui ne correspond pas.": "It will not do anything: often a pin number that does not match.",
  "Vérifiez le numéro de broche dans le code.": "Check the pin number in the code.",
  "digitalWrite sur une broche jamais mise en sortie.": "digitalWrite on a pin never set as an output.",
  "Sur un AVR, HIGH n’active que le tirage interne : la LED s’allume à peine.": "On an AVR, HIGH only enables the internal pull-up: the LED barely lights up.",
  "Ajoutez pinMode(broche, OUTPUT) dans setup().": "Add pinMode(pin, OUTPUT) in setup().",
  "Une sortie de la carte est reliée à la sortie d’un capteur.": "A board output is connected to a sensor’s output.",
  "Les deux sorties se contredisent : court-circuit possible.": "The two outputs fight each other: possible short circuit.",
  "Mettez la broche en entrée (pinMode INPUT).": "Set the pin as an input (pinMode INPUT).",
