  "Garantie dans le modèle de Jollof : calcul en courant continu (PWM moyennée, impulsions bornées par l’état haut), valeurs nominales des composants, servo et moteurs au pire. Un montage vérifié ne grille aucun composant dans aucun état atteignable de ce modèle.": "Guaranteed within Jollof’s model: DC calculation (averaged PWM, pulses bounded by their high state), component ratings, servos and motors at worst case. A checked circuit burns out no component in any reachable state of this model.",
