  "haut": "high",
  "bas": "low",
  "L’entrée VIN (ou VSYS) d’une carte reçoit plus que ce que son régulateur admet.": "A board’s VIN (or VSYS) input receives more than its regulator accepts.",
  "Le régulateur chauffe puis grille, et la carte avec lui (Pico : VSYS au plus 5,5 V ; Uno : 7 à 12 V conseillés).": "The regulator overheats and burns out, taking the board with it (Pico: VSYS 5.5 V at most; Uno: 7 to 12 V recommended).",
  "Alimentez la carte dans sa plage, ou passez par un régulateur (LM7805) avant VIN.": "Power the board within its range, or add a regulator (LM7805) before VIN.",
  "L’entrée VIN d’une carte reçoit moins que le minimum de son régulateur.": "A board’s VIN input receives less than its regulator’s minimum.",
  "Sur pile seule, la carte redémarre sans cesse ou ne démarre pas ; tant que l’USB est branché, il la fait tourner et le problème se cache.": "On the battery alone, the board keeps resetting or never starts; while USB is plugged in, USB runs it and hides the problem.",
  "Prenez une pile ou un accu dans la plage de VIN (Uno : 7 à 12 V), ou alimentez la carte par l’USB.": "Use a battery within VIN’s range (Uno: 7 to 12 V), or power the board over USB.",
  "Dans au moins un état, un transistor dissipe plus que sa puissance (BC547 : 500 mW, PN2222A : 625 mW).": "In at least one state, a transistor dissipates more than its rating (BC547: 500 mW, PN2222A: 625 mW).",
  "Il n’est pas saturé : il chauffe au lieu de commuter, puis grille.": "It is not saturated: it heats up instead of switching, then burns out.",
  "Donnez plus de courant de base (résistance de base plus petite) pour le saturer, ou prenez un transistor plus gros.": "Give it more base current (a smaller base resistor) to saturate it, or use a bigger transistor.",
  "Dans au moins un état, le régulateur LM7805 dissipe trop sans radiateur.": "In at least one state, the LM7805 regulator dissipates too much without a heatsink.",
  "Il perd en chaleur (tension d’entrée − 5 V) × courant. Au-delà de 1 W il brûle au toucher ; vers 1,3 W sa protection thermique coupe la sortie et le montage s’éteint.": "It turns (input voltage − 5 V) × current into heat. Above 1 W it burns to the touch; around 1.3 W its thermal protection cuts the output and the circuit goes dead.",
  "Baissez la tension d’entrée (une pile 7,5 V plutôt que 12 V), réduisez le courant, ou vissez un radiateur.": "Lower the input voltage (7.5 V rather than 12 V), reduce the current, or screw on a heatsink.",
  "Deux modules I2C d’une même carte ont la même adresse.": "Two I2C modules on the same board have the same address.",
  "Ils répondent ensemble : les données se mélangent et aucun ne fonctionne correctement.": "They answer together: the data gets mixed up and neither works properly.",
  "Changez l’adresse de l’un (broche SDO du BMP280, AD0 du MPU6050, cavaliers A0–A2 de l’adaptateur LCD) ou mettez-le sur une autre carte.": "Change one module’s address (BMP280 SDO pin, MPU6050 AD0, A0–A2 jumpers of the LCD adapter) or move it to another board.",
  "Une broche lue au démarrage est tirée au mauvais niveau par le montage.": "A pin read at boot is pulled to the wrong level by the circuit.",
  "ESP32 : D12 haut met la flash à 1,8 V, D2 haut empêche le téléversement. ESP8266 : D3 ou D4 bas, ou D8 haut, et le programme ne démarre pas.": "ESP32: D12 high sets the flash to 1.8 V, D2 high prevents uploading. ESP8266: D3 or D4 low, or D8 high, and the program does not start.",
  "Déplacez ce signal sur une autre broche ; gardez ces broches pour des sorties (LED) ou laissez-les libres.": "Move this signal to another pin; keep these pins for outputs (LEDs) or leave them free.",
