  "E, B, C, face plate vers soi": "E, B, C, flat side facing you",
  "Même principe que le BC547, en plus robuste : 2 à 4 mA de base, à travers 1 kΩ, le saturent pour quelques centaines de mA. Saturé, il ne perd que Vce(sat) × Ic, quelques dizaines de mW.": "Same principle as the BC547, but sturdier: 2 to 4 mA of base current through 1 kΩ saturates it for a few hundred mA. Saturated, it only loses Vce(sat) × Ic, a few tens of mW.",
  "Base : vers la broche de la carte, via 1 kΩ": "Base: to the board pin, through 1 kΩ",
  "Collecteur : vers le − de la charge": "Collector: to the load’s −",
  "Ventilateur, pompe, vibreur commandés en PWM": "Fan, pump, vibration motor controlled with PWM",
  "Bande de LED courte, petit relais nu": "Short LED strip, small bare relay",
  "Confondre son brochage (E-B-C) avec celui du BC547 (C-B-E).": "Mixing up its pinout (E-B-C) with the BC547’s (C-B-E).",
  "Base trop peu alimentée (10 kΩ) : il reste en régime linéaire et chauffe.": "Too little base current (10 kΩ): it stays in the linear region and heats up.",
  "Oublier la diode de roue libre aux bornes d’un moteur.": "Forgetting the flyback diode across a motor.",
  "Voies": "Channels",
  "4, bidirectionnelles": "4, bidirectional",
  "Côté LV": "LV side",
  "1,8 à 3,6 V (le 3,3 V de la carte ou du module)": "1.8 to 3.6 V (the 3.3 V of the board or module)",
  "Côté HV": "HV side",
  "jusqu’à 5,5 V (le 5 V)": "up to 5.5 V (the 5 V)",
  "un MOSFET BSS138 et deux résistances de 10 kΩ par voie": "one BSS138 MOSFET and two 10 kΩ resistors per channel",
  "I2C 400 kHz, SPI quelques MHz, série": "I2C 400 kHz, SPI a few MHz, serial",
  "Au repos, chaque côté est tiré à sa propre tension par 10 kΩ. Quand le côté 3,3 V passe à LOW, le MOSFET conduit et tire aussi le côté 5 V à LOW ; quand c’est le côté 5 V, la diode interne puis le MOSFET tirent le côté 3,3 V. Aucun côté ne reçoit jamais la tension de l’autre.": "At rest, each side is pulled to its own voltage by 10 kΩ. When the 3.3 V side goes LOW, the MOSFET conducts and pulls the 5 V side LOW too; when the 5 V side goes LOW, the body diode and then the MOSFET pull the 3.3 V side down. Neither side ever sees the other side’s voltage.",
  "5 V": "5 V",
  "Signaux côté 3,3 V": "Signals on the 3.3 V side",
  "Signaux côté 5 V (même numéro = même signal)": "Signals on the 5 V side (same number = same signal)",
