  "Servo.h ne fonctionne pas sur l’ESP32 : installez la bibliothèque ESP32Servo et écrivez #include <ESP32Servo.h>": "Servo.h does not work on the ESP32: install the ESP32Servo library and write #include <ESP32Servo.h>",
  "pulseIn({0}) : le TRIG du HC-SR04 n’est relié à aucune broche de {1}, le module n’envoie jamais d’écho": "pulseIn({0}): the HC-SR04 TRIG is not connected to any pin of {1}, so the module never sends an echo",
  "pulseIn({0}) : aucune impulsion sur TRIG ({1}) avant la mesure. Le HC-SR04 n’envoie un écho qu’après digitalWrite(TRIG, HIGH), delayMicroseconds(10), digitalWrite(TRIG, LOW)": "pulseIn({0}): no pulse on TRIG ({1}) before the measurement. The HC-SR04 only sends an echo after digitalWrite(TRIG, HIGH), delayMicroseconds(10), digitalWrite(TRIG, LOW)",
  "pulseIn({0}) : l’impulsion sur TRIG dure {1} µs, il en faut au moins 10 : le HC-SR04 ne réagit pas": "pulseIn({0}): the TRIG pulse lasts {1} µs, it needs at least 10: the HC-SR04 does not react",
  "pulseIn({0}) appelé trop tard après l’impulsion sur TRIG : l’écho a déjà commencé, la mesure échoue": "pulseIn({0}) called too late after the TRIG pulse: the echo has already started, the measurement fails",
