  "NEO_KHZ400 : les LED WS2812B attendent un signal à 800 kHz (NEO_KHZ800), elles ne comprennent pas celui-ci": "NEO_KHZ400: WS2812B LEDs expect an 800 kHz signal (NEO_KHZ800), they do not understand this one",
  "NEO_GRBW et NEO_RGBW sont prévus pour des LED à quatre couleurs : sur cette barrette RGB, les couleurs seraient décalées": "NEO_GRBW and NEO_RGBW are meant for four-colour LEDs: on this RGB strip, the colours would be shifted",
