  "Clavier matriciel 4×4 : 16 touches sur 8 fils, 4 lignes (R1 à R4) et 4 colonnes (C1 à C4). Une touche appuyée relie sa ligne à sa colonne.": "4×4 matrix keypad: 16 keys on 8 wires, 4 rows (R1 to R4) and 4 columns (C1 to C4). A pressed key connects its row to its column.",
  "Ligne : lue avec la résistance de tirage interne (INPUT_PULLUP). Elle passe à LOW quand on appuie sur une touche de la colonne en cours de balayage.": "Row: read with the internal pull-up (INPUT_PULLUP). It goes LOW when a key of the column being scanned is pressed.",
  "Colonne : la bibliothèque Keypad la met à LOW à son tour pour balayer le clavier ; le reste du temps, elle reste en entrée.": "Column: the Keypad library sets it LOW in turn to scan the keypad; the rest of the time it stays an input.",
  "RF24 radio({0}, {1});\nconst byte adresse[6] = \"00001\";\n// émetteur, setup() : radio.begin(); radio.openWritingPipe(adresse); radio.stopListening();\nint valeur = 42;\nradio.write(&valeur, sizeof(valeur));\n// récepteur, setup() : radio.begin(); radio.openReadingPipe(1, adresse); radio.startListening();\n// loop() : if (radio.available()) radio.read(&valeur, sizeof(valeur));": "RF24 radio({0}, {1});\nconst byte adresse[6] = \"00001\";\n// transmitter, setup(): radio.begin(); radio.openWritingPipe(adresse); radio.stopListening();\nint valeur = 42;\nradio.write(&valeur, sizeof(valeur));\n// receiver, setup(): radio.begin(); radio.openReadingPipe(1, adresse); radio.startListening();\n// loop(): if (radio.available()) radio.read(&valeur, sizeof(valeur));",
  "// téléphone → carte : if ({0}.available()) { char c = {0}.read(); }\n// carte → téléphone : {0}.println(\"Bonjour\");": "// phone → board: if ({0}.available()) { char c = {0}.read(); }\n// board → phone: {0}.println(\"Hello\");",
  "{0}.println(\"AT+CMGF=1\"); // SMS en mode texte\n{0}.println(\"AT+CMGS=\\\"+221770000000\\\"\");\n{0}.print(\"Bonjour\");\n{0}.write(26); // Ctrl+Z : le SMS part": "{0}.println(\"AT+CMGF=1\"); // SMS in text mode\n{0}.println(\"AT+CMGS=\\\"+221770000000\\\"\");\n{0}.print(\"Hello\");\n{0}.write(26); // Ctrl+Z: the SMS is sent",
  "radio.write(&texte, …) : une String n’est pas un tableau d’octets, la radio enverrait son adresse en mémoire. Utilisez un tableau de char : char texte[32]": "radio.write(&texte, …): a String is not a byte array, the radio would send its memory address. Use a char array: char texte[32]",
  "radio.read(&texte, …) : une String n’est pas un tableau d’octets. Recevez dans un tableau de char : char texte[32]": "radio.read(&texte, …): a String is not a byte array. Receive into a char array: char texte[32]",
  // textes des modules (adresse LCD, ADC)
  "analogRead() : de 0 à 1023 (UNO, Nano, ESP8266, Pico) ou 4095 (ESP32).": "analogRead(): from 0 to 1023 (UNO, Nano, ESP8266, Pico) or 4095 (ESP32).",
  "Écran LCD 16 caractères × 2 lignes avec adaptateur I2C (PCF8574), adresse 0x27 (0x3F avec une puce PCF8574A).": "16 × 2 character LCD with I2C adapter (PCF8574), address 0x27 (0x3F with a PCF8574A chip).",
  "Mauvaise adresse : 0x27 pour un adaptateur PCF8574, 0x3F pour un PCF8574A (le scanner I2C la donne).": "Wrong address: 0x27 for a PCF8574 adapter, 0x3F for a PCF8574A (the I2C scanner tells you).",
  // vérificateur : sous-montages indépendants
  "Garantie dans le modèle de Jollof : calcul en courant continu (PWM moyennée, impulsions bornées par l’état haut), valeurs nominales des composants, servo et moteurs au pire, broches 5V et 3V3 des cartes tenues à leur tension (ce qui rend leurs sous-montages indépendants). Un montage vérifié ne grille aucun composant dans aucun état atteignable de ce modèle.": "Guaranteed within Jollof’s model: DC calculation (averaged PWM, pulses bounded by their high state), component ratings, servos and motors at their worst, boards’ 5V and 3V3 pins held at their voltage (which makes their sub-circuits independent). A checked circuit burns no component in any reachable state of this model.",
  // Wi-Fi, Bluetooth, EEPROM/Preferences, ESP-NOW, appels SIM800, mode AT HC-05
