  "Au-delà de 25 Hz, la simulation en direct ne voit que la moyenne ({0}) : l’oscilloscope en mode Lab analogique montre le vrai signal.": "Above 25 Hz, the live simulation only sees the mean ({0}): the oscilloscope in Analog lab mode shows the real signal.",
