  // ESP32 fidèle (QEMU, bêta)
  "redémarrage logiciel (ESP.restart() ou plantage)": "software restart (ESP.restart() or crash)",
  "chien de garde": "watchdog",
  "réveil du sommeil profond": "wake-up from deep sleep",
  "Émulateur ESP32 indisponible.": "ESP32 emulator unavailable.",
  "— l’ESP32 redémarre : {0} —": "— the ESP32 restarts: {0} —",
  "L’ESP32 redémarre sans cesse ({0}) : programme arrêté. Vérifiez le moniteur série.": "The ESP32 keeps restarting ({0}): program stopped. Check the serial monitor.",
  "plantage ({0})": "crash ({0})",
  "assertion non vérifiée : {0}": "failed assertion: {0}",
  "abort()": "abort()",
  "Le programme a planté : {0}.": "The program crashed: {0}.",
  "L’émulateur ESP32 s’est arrêté (code {0}){1}": "The ESP32 emulator stopped (code {0}){1}",
  "L’ESP32 ne donne plus signe de vie depuis {0} s (programme bloqué, interruptions coupées ?).": "The ESP32 has not responded for {0} s (program stuck, interrupts disabled?).",
  "Wi-Fi et Bluetooth ne sont pas émulés en mode fidèle de l’ESP32 (bêta) : ce programme ({0}) tourne en mode Débutant, avec le Wi-Fi simulé.": "Wi-Fi and Bluetooth are not emulated in the ESP32 faithful mode (beta): this program ({0}) runs in Beginner mode, with the simulated Wi-Fi.",
  "Mode fidèle de l’ESP32 (bêta) : {0} ne répondront pas. Les modules I2C, SPI, 1-Wire et à signaux temporisés ne sont pas encore reliés à l’émulateur ; passez en mode Débutant pour les utiliser.": "ESP32 faithful mode (beta): {0} will not respond. I2C, SPI, 1-Wire and timed-signal modules are not connected to the emulator yet; switch to Beginner mode to use them.",
  "— {0} démarre : vrai programme dans l’émulateur de l’ESP32 (QEMU, bêta) —": "— {0} starts: real program in the ESP32 emulator (QEMU, beta) —",
  "Installer": "Install",
  "Mode fidèle de l’ESP32 (bêta) : le vrai programme tourne dans QEMU, l’émulateur d’Espressif. Pas de Wi-Fi ni de Bluetooth ; les modules I2C, SPI et 1-Wire ne répondent pas encore.": "ESP32 faithful mode (beta): the real program runs in QEMU, Espressif’s emulator. No Wi-Fi or Bluetooth; I2C, SPI and 1-Wire modules do not respond yet.",
  "Recherche de l’émulateur de l’ESP32…": "Looking for the ESP32 emulator…",
  "Le mode fidèle de l’ESP32 fait tourner le vrai programme dans un émulateur (QEMU) : il demande l’application installée. La carte tourne en mode Débutant.": "The ESP32 faithful mode runs the real program in an emulator (QEMU): it needs the installed app. The board runs in Beginner mode.",
  "L’émulateur de l’ESP32 (QEMU) n’est pas encore disponible pour cet ordinateur. La carte tourne en mode Débutant.": "The ESP32 emulator (QEMU) is not available for this computer yet. The board runs in Beginner mode.",
  "Le mode fidèle de l’ESP32 (bêta) fait tourner le vrai programme dans QEMU, l’émulateur d’Espressif : un programme à part d’environ 7 Mo, téléchargé une seule fois. En attendant, la carte tourne en mode Débutant.": "The ESP32 faithful mode (beta) runs the real program in QEMU, Espressif’s emulator: a separate program of about 7 MB, downloaded once. Until then, the board runs in Beginner mode.",
  "Téléchargement de l’émulateur de l’ESP32…": "Downloading the ESP32 emulator…",
  "Téléchargement de l’émulateur de l’ESP32… {0} %": "Downloading the ESP32 emulator… {0}%",
  "Téléchargement de l’émulateur de l’ESP32… {0} Mo": "Downloading the ESP32 emulator… {0} MB",
  "Émulateur de l’ESP32 installé : le mode fidèle est prêt.": "ESP32 emulator installed: the faithful mode is ready.",
  "Installation de l’émulateur de l’ESP32 impossible : {0}": "Could not install the ESP32 emulator: {0}",
