  "Ajoutez une horloge (Entrées → Horloge) pour faire avancer le temps.": "Add a clock (Inputs → Clock) to make time move forward.",
  "Ajoutez une horloge (Entrées → Horloge) pour avancer d’un front.": "Add a clock (Inputs → Clock) to step one edge forward.",
  "Attention : deux sorties reliées entre elles. Si elles ne donnent pas le même niveau, le fil passe en X (conflit).": "Careful: two outputs are connected together. If they don’t give the same level, the wire turns X (conflict).",
