  "Plusieurs interrupteurs côte à côte : ils forment un nombre binaire. Le bit 0 (poids faible) est en haut. Cliquez sur un interrupteur pour le basculer.": "Several switches side by side: they form a binary number. Bit 0 (least significant) is at the top. Click a switch to flip it.",
