  "Niveaux logiques": "Logic levels",
  "inconnu": "unknown",
  "Plan de travail logique": "Logic workspace",
  "Glissez des portes depuis la bibliothèque, puis tirez des fils de broche en broche. Cliquez sur un interrupteur pour le basculer : les fils à 1 s’allument.": "Drag gates from the library, then draw wires from pin to pin. Click a switch to flip it: wires at 1 light up.",
  "TP de logique": "Logic labs",
  "Bascules, compteurs et temps remis à zéro.": "Flip-flops, counters and time reset to zero.",
  "Bibliothèque logique": "Logic library",
  "Éléments courants": "Common elements",
  "Déplier la bibliothèque · Ctrl+B": "Expand the library · Ctrl+B",
  "Rechercher : ET, bascule D, compteur…": "Search: AND, D flip-flop, counter…",
  "Rechercher un élément logique": "Search for a logic element",
  "Aucun élément ne correspond à cette recherche.": "No element matches this search.",
  "Remplacer le circuit logique actuel par cet exemple ? Ctrl+Z permet de revenir en arrière.": "Replace the current logic circuit with this example? Ctrl+Z takes you back.",
  "Remplacer": "Replace",
  "Circuit": "Circuit",
  "Table": "Table",
  "Chronogramme": "Timing",
  "{0} élément{1} · {2} fil{3}": "{0} element{1} · {2} wire{3}",
  "Broche → broche : tirer un fil · clic sur un interrupteur : le basculer · R : tourner · Molette : zoom · Espace + glisser : se déplacer": "Pin → pin: draw a wire · click a switch: flip it · R: rotate · Wheel: zoom · Space + drag: pan",
  "entrée facultative ({0})": "optional input ({0})",
  "liaison": "link",
  "Tourner": "Rotate",
  "{0} éléments sélectionnés": "{0} elements selected",
  "Glissez-les ensemble, tournez-les (R), copiez-les (Ctrl+C, Ctrl+V) ou supprimez-les (Suppr).": "Drag them together, rotate them (R), copy them (Ctrl+C, Ctrl+V) or delete them (Del).",
  "Un fil relie des broches : elles prennent toutes le même niveau. Tirez depuis un fil pour en faire partir un autre (un nœud apparaît).": "A wire connects pins: they all take the same level. Drag from a wire to branch another one off it (a junction appears).",
  "Redresser": "Straighten",
  "{0} : l’entrée {1} n’est reliée à rien (niveau inconnu).": "{0}: input {1} is not connected to anything (unknown level).",
  "{0} fil(s) reliant des sorties qui se contredisent (X, en rouge).": "{0} wire(s) connecting outputs that disagree (X, in red).",
  "Le circuit oscille : une boucle ne trouve pas d’état stable.": "The circuit oscillates: a loop never reaches a stable state.",
  "Le repère {0} est utilisé {1} fois : chaque entrée et sortie doit avoir un nom différent.": "The label {0} is used {1} times: each input and output needs a different name.",
  "Ajoutez des interrupteurs (bibliothèque → Entrées) : chacun reçoit un nom, A, B, C…": "Add switches (library → Inputs): each one gets a name, A, B, C…",
  "Ajoutez des LED ou des sondes (bibliothèque → Sorties) pour lire les résultats.": "Add LEDs or probes (library → Outputs) to read the results.",
  "Vérifications": "Checks",
  "Toutes les entrées sont reliées, aucun conflit.": "All inputs are connected, no conflict.",
  "Plan de travail vide.": "Empty workspace.",
  "Mode d’emploi": "How to use",
  "<b>Poser</b> : glissez un élément depuis la bibliothèque (ou cliquez-le, puis cliquez sur le plan de travail).": "<b>Place</b>: drag an element from the library (or click it, then click the workspace).",
  "<b>Câbler</b> : tirez d’une broche à une autre. Relâché dans le vide, le fil continue : chaque clic pose un coude.": "<b>Wire</b>: drag from one pin to another. Released on empty space, the wire continues: each click adds a bend.",
  "<b>Brancher sur un fil</b> : tirez depuis un fil existant, ou terminez dessus.": "<b>Branch off a wire</b>: drag from an existing wire, or finish on it.",
  "<b>Tester</b> : cliquez sur un interrupteur ; un bouton-poussoir vaut 1 tant qu’on appuie.": "<b>Test</b>: click a switch; a push button is 1 while pressed.",
  "<b>Raccourcis</b> : R tourner, Suppr effacer, Ctrl+D dupliquer, F cadrer, T avancer d’un front, Espace + glisser pour se déplacer.": "<b>Shortcuts</b>: R rotate, Del delete, Ctrl+D duplicate, F fit, T step one edge, Space + drag to pan.",
  "Pas encore de table de vérité": "No truth table yet",
  "Il faut au moins une entrée (interrupteur, bouton, bloc DIP) et une sortie (LED, sonde, afficheur hexadécimal), chacune avec un nom.": "You need at least one input (switch, button, DIP block) and one output (LED, probe, hex display), each with a name.",
  "Trop d’entrées": "Too many inputs",
  "La table est calculée jusqu’à 8 entrées ({0} ici).": "The table is computed for up to 8 inputs ({0} here).",
  "(lignes inconnues comptées comme indifférentes)": "(unknown rows counted as don’t-care)",
  "Copier": "Copy",
  "Circuit séquentiel (mémoire) : la sortie dépend aussi de l’état mémorisé. Cette table est celle obtenue en essayant les lignes dans l’ordre ; préférez le chronogramme.": "Sequential circuit (memory): the output also depends on the stored state. This table is what you get trying the rows in order; prefer the timing diagram.",
  "Table de vérité": "Truth table",
  "Enregistrer la table (tableur, .csv)": "Save the table (spreadsheet, .csv)",
  "Cliquez sur une ligne : les entrées prennent ces valeurs sur le plan de travail.": "Click a row: the inputs take those values on the workspace.",
  "Équations": "Equations",
  "Simplifiées": "Simplified",
  "Canoniques": "Canonical",
  "Notation : · ET, + OU, barre au-dessus : NON.": "Notation: · AND, + OR, bar above: NOT.",
  "Tableau de Karnaugh": "Karnaugh map",
  "Équation copiée.": "Equation copied.",
  "Rien d’enregistré": "Nothing recorded",
  "Nommez des entrées et des sorties, puis lancez l’horloge (▶ sous le plan de travail) ou basculez les interrupteurs : chaque changement s’inscrit ici.": "Name inputs and outputs, then run the clock (▶ under the workspace) or flip the switches: every change is recorded here.",
  "Ajoutez un signal interne (sortie d’une bascule, d’une porte) : clic droit sur l’élément, « Afficher au chronogramme ».": "Add an internal signal (a flip-flop or gate output): right-click the element, “Show in the timing diagram”.",
  "Un laboratoire d’électronique sans matériel : chaque TP part d’un montage, guide pas à pas et vérifie votre travail (câblage, programme, comportement, mesures au multimètre).": "An electronics lab without equipment: each lab starts from a circuit, guides you step by step and checks your work (wiring, program, behaviour, multimeter measurements).",
  "Portes, bascules, compteurs : chaque TP ouvre le plan de travail logique avec ses entrées et ses sorties, et vérifie la table de vérité, la chronologie ou l’équation de votre circuit.": "Gates, flip-flops, counters: each lab opens the logic workspace with its inputs and outputs, and checks your circuit’s truth table, sequence or equation.",
  "Équation juste, mais écrivez-la comme une somme de produits : des termes reliés par +, chacun fait de lettres (barrées ou non) reliées par « . ».": "Correct equation, but write it as a sum of products: terms joined by +, each made of letters (barred or not) joined by “.”.",
  "Équation juste, mais écrivez-la comme un produit de sommes, par exemple (A + B).(/A + C).": "Correct equation, but write it as a product of sums, for example (A + B).(/A + C).",
  "Équation juste, mais écrivez-la comme un seul produit de lettres, barrées ou non (par exemple /A./B).": "Correct equation, but write it as a single product of letters, barred or not (for example /A./B).",
  "Équation juste, mais sans le symbole ^ : écrivez-la avec « . », « + » et « / ».": "Correct equation, but without the ^ symbol: write it with “.”, “+” and “/”.",
