  "L’assistant IA veut remplacer « {0} » par un autre projet. Les modifications non enregistrées seront perdues.": "The AI assistant wants to replace “{0}” with another project. Unsaved changes will be lost.",
  "Laisser votre assistant IA (Claude, Cursor, VS Code…) piloter Jollof Studio": "Let your AI assistant (Claude, Cursor, VS Code…) drive Jollof Studio",
  "Votre assistant IA (Claude, Cursor, VS Code…) peut piloter Jollof Studio : poser et câbler des composants, écrire le programme, simuler, créer des composants, sans copier-coller.": "Your AI assistant (Claude, Cursor, VS Code…) can drive Jollof Studio: place and wire parts, write the program, simulate, create parts, with no copy and paste.",
  "Cette fonction est dans l’application de bureau Jollof Studio (Mac, Windows, Linux) : un navigateur ne peut pas recevoir les commandes d’un assistant.": "This feature is in the Jollof Studio desktop app (Mac, Windows, Linux): a browser cannot receive an assistant’s commands.",
  "Votre assistant IA pilote Jollof Studio : il pose et câble les composants, écrit le programme, lance la simulation, lit les mesures et crée de nouveaux composants. Chaque action s’annule avec Ctrl+Z.": "Your AI assistant drives Jollof Studio: it places and wires the parts, writes the program, runs the simulation, reads the measurements and creates new parts. Every action can be undone with Ctrl+Z.",
  "Autoriser les assistants IA sur cet ordinateur": "Allow AI assistants on this computer",
  "Vos assistants": "Your assistants",
  "« Relier » ajoute Jollof Studio à la configuration de l’assistant ; ensuite, il suffit de lui parler (« fais-moi une station météo sur un ESP32 »).": "“Connect” adds Jollof Studio to the assistant’s configuration; then just talk to it (“build me a weather station on an ESP32”).",
  "Autre assistant compatible MCP": "Other MCP-compatible assistant",
  "Déclarez un serveur MCP « stdio » qui lance cette commande :": "Declare a “stdio” MCP server that runs this command:",
  "Accès": "Access",
  "Seul ce compte de l’ordinateur peut relier un assistant : la clé d’accès reste dans un fichier que lui seul peut lire, et chaque nouvel assistant demande votre accord. Une page web ne peut pas piloter l’application.": "Only this computer account can connect an assistant: the access key stays in a file only it can read, and every new assistant asks for your approval. A web page cannot drive the app.",
