  "Les assistants connectés sont déconnectés, la clé d’accès change et chaque assistant redemandera votre accord. Les assistants reliés restent configurés.": "Connected assistants are disconnected, the access key changes and every assistant will ask for your approval again. Connected assistants stay configured.",
