  "« {0} » demande à piloter Jollof Studio : poser et câbler des composants, écrire le programme, simuler, créer des composants. Chaque action s’annule avec Ctrl+Z.": "“{0}” asks to drive Jollof Studio: place and wire parts, write the program, simulate, create parts. Every action can be undone with Ctrl+Z.",
