  "pinMode({0}, INPUT_PULLUP); // piston absent : HIGH, piston devant le capteur : LOW": "pinMode({0}, INPUT_PULLUP); // piston away: HIGH, piston in front of the sensor: LOW",
  "pinMode({0}, OUTPUT); // base de {1} : HIGH, le transistor conduit et {2} est excitée": "pinMode({0}, OUTPUT); // base of {1}: HIGH, the transistor conducts and {2} is energised",
