  "Réceptivité illisible : {0}": "Unreadable receptivity: {0}",
  "Le GRAFCET n’a aucune étape.": "The GRAFCET has no step.",
  "// GRAFCET : une variable par étape, vraie quand l’étape est active.": "// GRAFCET: one variable per step, true while the step is active.",
  "unsigned long debutX{0} = 0; // instant d’activation de X{0} (temporisation)": "unsigned long debutX{0} = 0; // time X{0} was activated (time delay)",
  "bool {0} = false; // valeur de {1} au tour précédent (front)": "bool {0} = false; // value of {1} on the previous loop (edge)",
  "// 1. Transitions franchissables : toutes calculées avant d’évoluer (franchissement simultané).": "// 1. Clearable transitions: all computed before evolving (simultaneous clearing).",
  "// 2. Évolution : on désactive les étapes amont, puis on active les étapes aval.": "// 2. Evolution: deactivate the upstream steps, then activate the downstream ones.",
  "// 3. Fronts : valeur de ce tour, comparée au prochain.": "// 3. Edges: this loop’s value, compared on the next one.",
  "// Sorties : chacune est commandée tant qu’une étape qui la porte est active.": "// Outputs: each is driven while a step that carries it is active.",
  "// {0} : aucun effecteur de ce nom sur la carte (commandé si {1}).": "// {0}: no actuator with this name on the board (driven when {1}).",
  "// Programme de {0}, écrit par Jollof Studio à partir du GRAFCET du plan pneumatique.": "// Program of {0}, written by Jollof Studio from the GRAFCET of the pneumatic workspace.",
  "// Une évolution par tour de loop() ; vous pouvez le modifier librement.": "// One evolution per loop(); you can edit it freely.",
  "Ajoutez une carte (Arduino Uno…) au montage électronique : le programme est écrit pour elle.": "Add a board (Arduino Uno…) to the electronics bench: the program is written for it.",
  "Cliquez sur « Observer », puis lancez le cycle : les courses des vérins sont relevées et comparées au cycle attendu.": "Click “Observe”, then start the cycle: the cylinder strokes are recorded and compared with the expected cycle.",
