  "Réceptivité": "Receptivity",
  "Expansion de M{0}": "Expansion of M{0}",
  "bool {0} = {1}; // {2} mémorisée (actions « {2}:=1 » et « {2}:=0 »)": "bool {0} = {1}; // {2} stored (actions “{2}:=1” and “{2}:=0”)",
  "GRAFCET avec macro-étape (M2 : perçage)": "GRAFCET with a macro-step (M2: drilling)",
  "Le même cycle A+ B+ B− A−, mais le perçage B+ B− est une macro-étape M2 : la transition qui y mène active son étape d’entrée (20), celle qui en sort attend son étape de sortie (22). L’expansion est dessinée sous le GRAFCET.": "The same A+ B+ B− A− cycle, but drilling B+ B− is a macro-step M2: the transition into it activates its entry step (20), the one leaving it waits for its exit step (22). The expansion is drawn below the GRAFCET.",
  "Branches parallèles et action mémorisée (trois vérins)": "Parallel branches and a stored action (three cylinders)",
  "A serre (1Y1:=1, action mémorisée : le distributeur monostable reste excité), puis B perce et C marque en même temps (divergence en ET) ; la convergence attend que les deux aient fini, puis 1Y1:=0 desserre.": "A clamps (1Y1:=1, a stored action: the monostable valve stays energised), then B drills and C marks at the same time (AND divergence); the convergence waits for both to finish, then 1Y1:=0 unclamps.",
