  "Nom du GRAFCET partiel": "Partial GRAFCET name",
  "forcé": "forced",
  "GRAFCET partiel {0}": "Partial GRAFCET {0}",
  "Ajouter un GRAFCET partiel (sécurité, forçage…)": "Add a partial GRAFCET (safety, forcing…)",
  "Supprimer ce GRAFCET partiel": "Delete this partial GRAFCET",
  "Retirer l’encapsulation": "Remove the encapsulation",
  "En faire une étape encapsulante": "Make it an enclosing step",
  "long {0} = {1}; // compteur {2}": "long {0} = {1}; // counter {2}",
  "// 0. Forçages : émis par les étapes actives, ils passent avant l’évolution du GRAFCET forcé.": "// 0. Forcing orders: emitted by active steps, they come before the forced GRAFCET evolves.",
  "// Situations imposées par les forçages ({*} : figé, rien ne change).": "// Situations imposed by forcing orders ({*}: frozen, nothing changes).",
  "// X{0} fige {1}.": "// X{0} freezes {1}.",
  "Arrêt d’urgence (forçage) et compteur de cycles": "Emergency stop (forcing) and cycle counter",
  "dcy lance trois cycles (compteur N:=N+1, réceptivités N<3 et N>=3). Le GRAFCET de sécurité GS surveille au : arrêt d’urgence, il force GPN en {0} (F/GPN:{0}) et fait rentrer les tiges ; relâchez au puis appuyez sur rea pour réarmer.": "dcy runs three cycles (counter N:=N+1, receptivities N<3 and N>=3). The safety GRAFCET GS watches au: on an emergency stop it forces GPN into {0} (F/GPN:{0}) and retracts the rods; release au then press rea to reset.",
  "Marche automatique (étape encapsulante)": "Automatic mode (enclosing step)",
  "marche active l’étape encapsulante X1 : son encapsulation enchaîne les cycles A+ B+ B− A−. Fermez arret : le cycle en cours se termine, X1 se désactive et toute son encapsulation avec elle.": "marche activates the enclosing step X1: its encapsulation chains A+ B+ B− A− cycles. Close arret: the current cycle finishes, X1 deactivates and its whole encapsulation with it.",
  // pneu/ : machine 3D
  "Vue 3D de la machine": "3D view of the machine",
  "Machine 3D": "3D machine",
  "Scène": "Scene",
  "Vérin de la porte": "Door cylinder",
