  "Fermer la vue 3D": "Close the 3D view",
  "Vérins du circuit": "Circuit cylinders",
  "Porte de TER": "TER door",
  "Ouvrir ({0})": "Open ({0})",
  "Simulation arrêtée : lancez-la avec « Simuler » pour voir la machine bouger.": "Simulation stopped: start it with “Simulate” to see the machine move.",
  "Comme le vrai bouton : appuyé tant que vous maintenez le clic (ou la barre d’espace). Maj + clic : le laisser appuyé.": "Like the real button: pressed while you hold the click (or the space bar). Shift + click: leave it pressed.",
  // supervision/ : supervision MA-ISA (états, surveillances, pannes simulées, démonstration, aide)
  "La démonstration ouvre le projet « Vérin électropneumatique ». Votre projet est mis de côté, tel quel : il revient quand vous quittez la démonstration.": "The demonstration opens the “Electropneumatic cylinder” project. Your project is set aside as it is: it comes back when you leave the demonstration.",
  "Démonstration terminée : votre projet est de retour.": "Demonstration closed: your project is back.",
  "Démonstration terminée.": "Demonstration closed.",
  "Quitter la démonstration": "Leave the demonstration",
  "Démonstration terminée : la supervision a vu que le vérin ne répondait plus, a demandé la mise en sécurité, puis vous a laissé reprendre en trois étapes. Essayez une autre panne, ou retrouvez votre projet.": "Demonstration complete: the supervision saw that the cylinder no longer responded, requested a safe state, then let you recover in three steps. Try another fault, or get back to your project.",
  "Si le vérin {0} ne bouge pas, la mise en sécurité est demandée {1} s après que {2} devient actif.": "If cylinder {0} does not move, the safe state is requested {1} s after {2} becomes active.",
  "Temps accordé pour sortir à mi-course": "Time allowed to reach mid-stroke",
  "Attention : cette broche passe de 0 à 5 V en fonctionnement normal, car elle est reliée à {0}. Surveillez plutôt {0} ou ce qu’il commande.": "Careful: this pin goes between 0 and 5 V in normal use, because it is wired to {0}. Watch {0} or what it drives instead.",
  "Quand {0} devient actif, le vérin {1} doit sortir au moins à {2} % en moins de {3} s.": "When {0} becomes active, cylinder {1} must extend at least {2} % within {3} s.",
  "Conseil : lancez d’abord la simulation sans panne et faites fonctionner le circuit : la surveillance doit rester « Normal ». Sinon, accordez plus de temps ou un écart plus large.": "Tip: first run the simulation without any fault and operate the circuit: the watch must stay “Normal”. Otherwise allow more time or a wider deviation.",
  "{0} ne doit jamais dépasser {1} {2}.": "{0} must never exceed {1} {2}.",
