  "La valeur reste bloquée, quoi qu’il arrive dans le circuit.": "The value stays stuck, whatever happens in the circuit.",
  "La position observée ne suit plus la commande, comme un vérin ou un moteur coincé.": "The observed position no longer follows the command, like a jammed cylinder or motor.",
