  "Un écart apparaît par moments, puis disparaît.": "A deviation appears now and then, then goes away.",
  "Supervision : un gardien qui surveille le circuit pendant la simulation": "Supervision: a guard that watches the circuit during the simulation",
  "Quand {0} devient actif, {1} doit atteindre {2} en moins de {3} s.": "When {0} becomes active, {1} must reach {2} within {3} s.",
