  "Mise en sécurité confirmée par l’opérateur": "Safe state confirmed by the operator",
  "Mise en sécurité non confirmée dans le délai : échec": "Safe state not confirmed in time: failed",
  "Trop de demandes sans réponse : escalade": "Too many unanswered requests: escalation",
  "Défaut d’horloge : pas de temps hors limites, niveaux figés": "Clock fault: time step out of bounds, levels held",
  "Vous : état sûr confirmé": "You: safe state confirmed",
