  // ui/kind.js : type de projet ; vérificateur : plan pneumatique (J07) ; lab : à retenir
  "À retenir": "Remember",
  "Ce qu’il faut retenir": "What to remember",
  "Tutoriel terminé !": "Tutorial complete!",
  "Ajouter au montage": "Add to the bench",
  "Les électrovannes et les capteurs se câblent à une carte. Ajouter une carte Arduino Uno au montage ? Le projet devient électropneumatique : le montage et le circuit pneumatique côte à côte.": "Solenoid valves and sensors are wired to a board. Add an Arduino Uno to the bench? The project becomes electropneumatic: the bench and the pneumatic circuit side by side.",
  "Ajouter la carte": "Add the board",
  "plan pneumatique": "pneumatic circuit",
  "{0} : aucun élément du plan pneumatique ne porte ce repère": "{0}: no element of the pneumatic circuit carries this tag",
  "Type de projet": "Project type",
  "Bobines et capteurs": "Coils and sensors",
  "Passer ce projet en « {0} » ? Ce qui appartient aux autres plans de travail reste enregistré dans le projet, mais n’est plus affiché ni simulé.": "Switch this project to “{0}”? What belongs to the other workspaces stays saved in the project, but is no longer shown or simulated.",
  "Changer de type": "Change type",
  "Projet {0}.": "{0} project.",
  "Nouveau projet {0}.": "New {0} project.",
  "Une carte (Arduino, ESP32, Pico), des capteurs, des écrans, des moteurs : on câble, on programme, on simule.": "A board (Arduino, ESP32, Pico), sensors, displays, motors: wire, program, simulate.",
  "Sans carte ni programme : résistances, condensateurs, transistors, NE555, ampli-op, générateur de fonctions et oscilloscope.": "No board, no program: resistors, capacitors, transistors, NE555, op-amp, function generator and oscilloscope.",
  "L’air comprimé seul : distributeurs, vérins, fins de course à galet, GRAFCET. Aucun montage électronique.": "Compressed air only: valves, cylinders, roller limit valves, GRAFCET. No electronic bench.",
  "Électropneumatique": "Electropneumatic",
  "Une carte commande une machine pneumatique : électrovannes 24 V, capteurs de vérin, les deux plans de travail côte à côte.": "A board drives a pneumatic machine: 24 V solenoid valves, cylinder sensors, both workspaces side by side.",
  "Portes, bascules, compteurs : tables de vérité, chronogrammes, équations.": "Gates, flip-flops, counters: truth tables, timing diagrams, equations.",
  "Deux plans de travail": "Two workspaces",
  "Un plan de travail": "One workspace",
  "Première fois en électropneumatique ?": "New to electropneumatics?",
  "Suivre le tutoriel pas à pas": "Follow the step-by-step tutorial",
  "{0}Nouveau projet : que voulez-vous construire ?": "{0}New project: what do you want to build?",
  "Type de projet : {0}. Cliquer pour en changer.": "Project type: {0}. Click to change it.",
  "Pneumatique et électropneumatique": "Pneumatics and electropneumatics",
  "Le circuit pneumatique ne peut pas fonctionner tel qu’il est dessiné.": "The pneumatic circuit cannot work as drawn.",
  "Sans source d’air, sans alimentation d’un distributeur (orifice 1) ou sans commande d’un électroaimant, l’air n’arrive pas ou le tiroir ne bascule jamais : le vérin reste immobile.": "Without an air supply, without supply to a valve (port 1) or without anything driving a solenoid, air never arrives or the spool never switches: the cylinder stays still.",
  "Raccordez l’orifice signalé, ajoutez la source, ou donnez à l’électroaimant le repère d’une électrovanne du montage (ou une action du GRAFCET).": "Connect the reported port, add the supply, or give the solenoid the tag of a solenoid valve on the bench (or a GRAFCET action).",
  "Un détail du circuit pneumatique mérite un regard.": "A detail of the pneumatic circuit deserves a look.",
  "Un orifice d’utilisation libre, un capteur sans contact dans le montage ou une bobine qui commande deux distributeurs fonctionnent parfois comme prévu, mais c’est rarement voulu.": "A free working port, a sensor with no contact on the bench or a coil driving two valves sometimes works as intended, but it is rarely on purpose.",
  "Raccordez ou renommez l’élément signalé ; si c’est voulu, acceptez l’avertissement en disant pourquoi.": "Connect or rename the reported element; if it is intended, accept the warning and say why.",
  "Le GRAFCET du plan pneumatique contient une erreur.": "The GRAFCET of the pneumatic circuit contains an error.",
  "Une réceptivité illisible, une transition vers une étape absente ou l’absence d’étape initiale empêchent le GRAFCET d’évoluer : la machine resterait bloquée.": "An unreadable receptivity, a transition to a missing step or no initial step keeps the GRAFCET from evolving: the machine would stay stuck.",
  "Ouvrez le panneau GRAFCET : l’étape fautive est marquée en rouge, avec le détail.": "Open the GRAFCET panel: the faulty step is marked in red, with the detail.",
  "Un composant du montage n’est relié à aucun élément du plan pneumatique.": "A bench part is linked to no element of the pneumatic circuit.",
  "Une électrovanne, un capteur de vérin ou un pressostat agit par son repère : sans élément du plan qui porte le même, la bobine ne fait basculer aucun distributeur et le contact ne se ferme jamais.": "A solenoid valve, a cylinder sensor or a pressure switch acts through its tag: with no circuit element carrying the same one, the coil switches no valve and the contact never closes.",
  "Donnez ce repère à la bobine d’un distributeur, au capteur d’un vérin ou à un pressostat du plan, ou retirez le composant.": "Give this tag to a valve coil, a cylinder sensor or a pressure switch of the circuit, or remove the part.",
  // lab/ : tutoriels (carte de l'étape, où cliquer, contrôles qui se vérifient seuls)
